-- public.pier_says(p_world uuid, p_x integer, p_y integer)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.pier_says(p_world uuid, p_x integer, p_y integer)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  select coalesce((
    select ' On piers: deck at ' || metres(b.deck) || ' m, ' || metres(pier_drop_at(p_world, p_x, p_y))
        || ' m above the lowest ground.'
        || case when deck_surface(p_world, p_x, p_y) is null
                then ' Deck not built: nothing stands on it yet.' else '' end
        -- And the water under it, where it has risen to within `pier_clear()` of the deck since it was planned.
        || case when g.water is not null and g.water + pier_clear() > b.deck
                then ' Water under it: ' || metres(g.water) || ' m, '
                  || case when g.water < b.deck then metres(b.deck - g.water) || ' m below the deck' else 'over the deck' end || '.'
                else '' end
      from building_tile bt join building b on b.world_id = bt.world_id and b.id = bt.building
      cross join pier_ground(p_world, p_x, p_y) g
     where bt.world_id = p_world and bt.x = p_x and bt.y = p_y and bt.pier and b.deck is not null), '')
$function$
